from pathlib import Path

p = Path('index.html')
s = p.read_text(encoding='utf-8')

s = s.replace('<div class="memory-info"><div class="memory-top"><span class="memory-word">${safe(x.word)}</span><span class="tag">${safe(x.category)}</span></div><div class="memory-clue">${safe(x.clue)}</div></div><span class="memory-date">${safe(x.date||\'오늘\')}</span>', '<div class="memory-info"><div class="memory-top"><span class="memory-word">${safe(x.word)}</span><span class="tag">${safe(x.category)}</span></div><div class="memory-clue">${safe(x.clue)}</div><div class="memory-detail">${x.meaning?`<span><b>뜻</b> ${safe(x.meaning)}</span>`:\'\'}${x.confused?`<span><b>헷갈린 단어</b> ${safe(x.confused)}</span>`:\'\'}${x.difference?`<span><b>차이</b> ${safe(x.difference)}</span>`:\'\'}</div></div><div class="memory-tools"><span class="memory-date">${safe(x.date||\'오늘\')}</span><button class="icon-btn edit-word" data-id="${safe(x.id)}" aria-label="수정">✎</button><button class="icon-btn delete-word" data-id="${safe(x.id)}" aria-label="삭제">×</button></div>')
s = s.replace('.memory-date{font:9px \'DM Mono\',monospace;color:#aaa99e;white-space:nowrap}', '.memory-date{font:9px \'DM Mono\',monospace;color:#aaa99e;white-space:nowrap}.memory-detail{display:flex;flex-wrap:wrap;gap:5px 12px;margin-top:7px;color:#74766d;font-size:10px;line-height:1.5}.memory-detail b{color:#98998f;font-weight:500;margin-right:3px}.memory-tools{display:flex;align-items:center;gap:4px;flex:none}.icon-btn{border:0;background:transparent;color:#929389;font-size:15px;padding:5px;border-radius:6px}.icon-btn:hover{background:#f0efe8;color:#31342c}')
s = s.replace('<div class="field"><label for="meaning">뜻 또는 예문</label><input id="meaning" placeholder="선택 사항"></div><div class="field"><label for="category">분류</label>', '<div class="field"><label for="meaning">뜻 또는 예문</label><input id="meaning" placeholder="이 단어의 뜻과 쓰임"></div><div class="field"><label for="confused">헷갈렸던 단어</label><input id="confused" placeholder="예: 기시감"></div><div class="field"><label for="difference">둘의 차이 설명</label><textarea id="difference" placeholder="어떤 점이 다르고, 언제 쓰는지"></textarea></div><div class="field"><label for="category">분류</label>')
s = s.replace("let items=JSON.parse(localStorage.getItem('eoreumotWords')||'null')||seed;let reviewIndex=0;", "let items=JSON.parse(localStorage.getItem('eoreumotWords')||'null')||seed;items=items.map((x,i)=>({...x,id:x.id||`legacy-${i}`}));let reviewIndex=0,editingId=null;")
s = s.replace("function render(){ $('#navCount')", "function render(){ $('#navCount')")
s = s.replace("searchNow($('#search').value)}function renderReview()", "searchNow($('#search').value);document.querySelectorAll('.edit-word').forEach(b=>b.onclick=()=>editWord(b.dataset.id));document.querySelectorAll('.delete-word').forEach(b=>b.onclick=()=>deleteWord(b.dataset.id))}function renderReview()")
s = s.replace("function toast(msg){", "function editWord(id){const x=items.find(v=>v.id===id);if(!x)return;editingId=id;$('#word').value=x.word;$('#clue').value=x.clue;$('#meaning').value=x.meaning||'';$('#confused').value=x.confused||'';$('#difference').value=x.difference||'';$('#category').value=x.category||'기타';$('.modal h2').textContent='기억의 조각 수정하기';$('.save-btn').textContent='수정 내용 저장하기　↗';$('#modalBack').classList.add('open');$('#word').focus()}function deleteWord(id){const x=items.find(v=>v.id===id);if(!x)return;if(!confirm(`\"${x.word}\" 단어 기록을 삭제할까요?`))return;items=items.filter(v=>v.id!==id);persist();toast('단어 기록을 삭제했어요')}function toast(msg){")
s = s.replace("function openModal(prefill=''){$('#modalBack').classList.add('open');$('#word').value='';$('#clue').value=prefill?`찾으려던 단서: ${prefill}\\n`:'';$('#word').focus()}", "function openModal(prefill=''){editingId=null;$('.modal h2').textContent='기억의 조각 남기기';$('.save-btn').textContent='기억 저장하기　↗';$('#wordForm').reset();$('#modalBack').classList.add('open');$('#clue').value=prefill?`찾으려던 단서: ${prefill}\\n`:'';$('#word').focus()}")
s = s.replace("$('#wordForm').onsubmit=e=>{e.preventDefault();items.unshift({word:$('#word').value.trim(),clue:$('#clue').value.trim(),meaning:$('#meaning').value.trim(),category:$('#category').value,date:'오늘',tone:['green','peach','lav'][items.length%3]});persist();$('#modalBack').classList.remove('open');e.target.reset();toast('기억의 조각을 저장했어요 ✳')};", "$('#wordForm').onsubmit=e=>{e.preventDefault();const entry={word:$('#word').value.trim(),clue:$('#clue').value.trim(),meaning:$('#meaning').value.trim(),confused:$('#confused').value.trim(),difference:$('#difference').value.trim(),category:$('#category').value,date:'오늘',tone:['green','peach','lav'][items.length%3]};if(editingId){const i=items.findIndex(x=>x.id===editingId);items[i]={...items[i],...entry};toast('기억의 조각을 수정했어요 ✳')}else{items.unshift({...entry,id:crypto.randomUUID()});toast('기억의 조각을 저장했어요 ✳')}persist();$('#modalBack').classList.remove('open');e.target.reset();editingId=null};")
p.write_text(s, encoding='utf-8')
